/// The packet name for an id, if the state and direction define it.
pub fn name(state: State, direction: Direction, id: i32) -> Option<&'static str> {
    let names: &[&str] = match (state, direction) {
        (State::Handshake, Direction::Serverbound) => handshake::serverbound::NAMES,
        (State::Status, Direction::Clientbound) => status::clientbound::NAMES,
        (State::Status, Direction::Serverbound) => status::serverbound::NAMES,
        (State::Login, Direction::Clientbound) => login::clientbound::NAMES,
        (State::Login, Direction::Serverbound) => login::serverbound::NAMES,
        (State::Configuration, Direction::Clientbound) => configuration::clientbound::NAMES,
        (State::Configuration, Direction::Serverbound) => configuration::serverbound::NAMES,
        (State::Play, Direction::Clientbound) => play::clientbound::NAMES,
        (State::Play, Direction::Serverbound) => play::serverbound::NAMES,
        _ => &[],
    };
    usize::try_from(id).ok().and_then(|i| names.get(i)).copied()
}
